WITH cleaned AS (SELECT *, TRIM(method) AS clean_method FROM payments WHERE order_id IS NOT NULL), flagged AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) + INTERVAL 30 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM cleaned), sessions_payments AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY status ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT DATE_TRUNC('YEAR', paid_at) AS year_start, COUNT(DISTINCT order_id) AS distinct_order_ids, SORT_ARRAY(COLLECT_SET(method)) AS method_list, COUNT(*) FILTER (WHERE method = 'paypal') AS paypal_rows, MIN(paid_at) AS first_paid_at FROM sessions_payments GROUP BY DATE_TRUNC('YEAR', paid_at) ORDER BY year_start DESC;
